const items = $input.all();
if (!items.length) return [];
const out = [];
for (const it of items) {
  const s = it.json || {};
  if (!s.instancia || !s.grupo_jid) continue;
  const cp = s.checkpoint ? Date.parse(s.checkpoint) : 0;
  const since = cp ? Math.floor(cp / 1000) - 120 : Math.floor(Date.now() / 1000);
  const esc = v => String(v == null ? '' : v).replace(/'/g, "''");
  const senders = [s.sender_jid, s.sender_lid].filter(Boolean).map(x => `'${esc(x)}'`).join(',');
  if (!senders) continue;
  const inst = esc(s.instancia), gj = esc(s.grupo_jid), gn = esc(s.grupo_nome), sj = esc(s.sender_jid), sn = esc(s.sender_nome), sid = esc(s.id);
  const query = `WITH base AS (
  SELECT m.key->>'id' AS msg_id, m."messageTimestamp" AS ts, m."pushName" AS push_name,
         COALESCE(NULLIF(m.key->>'participantAlt',''), m.key->>'participant') AS sender_jid,
         COALESCE(m.message->>'conversation', m.message->'extendedTextMessage'->>'text', m.message->'imageMessage'->>'caption', m.message->'videoMessage'->>'caption','') AS body
  FROM "Message" m JOIN "Instance" i ON i."id" = m."instanceId"
  WHERE i."name" = '${inst}' AND m.key->>'remoteJid' = '${gj}'
    AND NOT COALESCE((m.key->>'fromMe')::boolean, false)
    AND (m.key->>'participantAlt' IN (${senders}) OR m.key->>'participant' IN (${senders}))
    AND m."messageTimestamp" >= ${since}
    AND (COALESCE(m.message->>'conversation','') ILIKE '%instagram%' OR COALESCE(m.message->'extendedTextMessage'->>'text','') ILIKE '%instagram%' OR COALESCE(m.message->'imageMessage'->>'caption','') ILIKE '%instagram%' OR COALESCE(m.message->'videoMessage'->>'caption','') ILIKE '%instagram%' OR COALESCE(m.message->>'conversation','') ILIKE '%engaja.pro%' OR COALESCE(m.message->'extendedTextMessage'->>'text','') ILIKE '%engaja.pro%')
)
SELECT '${sid}' AS source_id, '${inst}' AS instancia, '${gj}' AS grupo_jid, '${gn}' AS grupo_nome, '${sj}' AS sender_jid, '${sn}' AS sender_nome,
       COALESCE(jsonb_agg(jsonb_build_object('msg_id',msg_id,'ts',ts,'push_name',push_name,'sender_jid',sender_jid,'body',body) ORDER BY ts),'[]')::text AS rows
FROM base`;
  out.push({ json: { source_id: s.id, instancia: s.instancia, grupo_jid: s.grupo_jid, grupo_nome: s.grupo_nome || '', sender_jid: s.sender_jid || '', sender_nome: s.sender_nome || '', since, query } });
}
return out;

const URL_RE = /https?:\/\/(?:www\.)?(?:instagram\.com|instagr\.am|engaja\.pro|vinculo\.pro)\/[^\s)'"]+/gi;
const clean = u => u.replace(/[?#].*$/, '').replace(/\/+$/, '');
const out = [];
for (const it of $input.all()) {
  const r = it.json || {};
  if (!r.rows) continue;
  let rows = [];
  try { rows = JSON.parse(r.rows) || []; } catch (e) { rows = []; }
  for (const m of rows) {
    const urls = [...new Set((String(m.body || '')).match(URL_RE) || [])].map(clean);
    if (!urls.length) continue;
    const tsIso = m.ts ? new Date(Number(m.ts) * 1000).toISOString() : null;
    for (const u of urls) {
      const isShort = /engaja\.pro|vinculo\.pro/.test(u);
      out.push({ json: {
        source_id: r.source_id, instancia: r.instancia, grupo_jid: r.grupo_jid, grupo_nome: r.grupo_nome,
        sender_jid: m.sender_jid || r.sender_jid, sender_nome: r.sender_nome,
        msg_id: m.msg_id, ts: tsIso, texto: String(m.body || ''),
        url_raw: u, precisa_resolver: isShort, slug: isShort ? (u.split('/').pop() || '') : ''
      }});
    }
  }
}
return out;

const sd = $getWorkflowStaticData('global');
const token = String(sd.vinculoToken || '');
return $input.all().filter(i => i.json && i.json.slug).map(i => ({ json: { ...i.json, vinculoToken: token } }));

const clean = u => u.replace(/[?#].*$/, '').replace(/\/+$/, '');
return $input.all().map(item => {
  const j = item.json || {};
  let dest = '';
  if (Array.isArray(j.items)) {
    const hit = j.items.find(x => x && x.destination_url && (!j.slug || !x.slug || x.slug === j.slug)) || j.items.find(x => x && x.destination_url);
    dest = hit ? String(hit.destination_url || '') : '';
  } else if (j.destination_url) { dest = String(j.destination_url); }
  const u = clean(dest);
  const isInsta = /instagram\.com|instagr\.am/.test(u);
  const short = String(j.url_raw || '');
  let url = '', short_url = '';
  if (dest && isInsta) { url = u; short_url = short; }
  else if (short) { url = short; short_url = short; }
  else { return { json: { __noop: true } }; }
  const m = url.match(/(?:reel|reels|p|tv)\/([A-Za-z0-9_-]+)/);
  return { json: { ...j, url, short_url, shortcode: m ? m[1] : '', kind: /\/reel/.test(url) ? 'reel' : 'post' } };
});

return $input.all().map(item => {
  const j = item.json || {};
  if (!j.url_raw) return { json: { __noop: true } };
  const u = String(j.url_raw);
  if (!/instagram\.com|instagr\.am/.test(u)) return { json: { __noop: true } };
  const m = u.match(/(?:reel|reels|p|tv)\/([A-Za-z0-9_-]+)/);
  return { json: { ...j, url: u, short_url: '', shortcode: m ? m[1] : '', kind: /\/reel/.test(u) ? 'reel' : 'post' } };
});

const byId = new Map();
for (const it of $input.all()) {
  const j = it.json || {};
  if (!j.msg_id || !j.url) continue;
  if (!byId.has(j.msg_id)) byId.set(j.msg_id, {
    source_id: j.source_id, instancia: j.instancia, grupo_jid: j.grupo_jid, grupo_nome: j.grupo_nome,
    sender_jid: j.sender_jid, sender_nome: j.sender_nome, msg_id: j.msg_id, ts: j.ts, texto: j.texto, links: []
  });
  const g = byId.get(j.msg_id);
  if (!g.links.some(l => l.url === j.url)) g.links.push({ url: j.url, short_url: j.short_url || '', shortcode: j.shortcode || '', kind: j.kind || '', orig_url: j.url_raw || '' });
}
return [...byId.values()].map(g => ({ json: g }));
